"""Run only after all24 analysis sheets were individually opened and reviewed."""
from pathlib import Path
import sys,json,hashlib,re
sys.dont_write_bytecode=True
from dsp import RECIPES,AMBIENCE_RECIPES,UI
R=Path(__file__).resolve().parents[3];O=R/'Art/Audio'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
m=json.loads((O/'metrics.json').read_text());v=json.loads((O/'verification.json').read_text())
assert m['result']==v['result']=='PASS' and v['files_verified']==66 and v['sheets_verified']==24
assert len(m['sheets'])==24
review=[]
for row in m['sheets']:
    assert sha(O/row['file'])==row['sha256'];review.append(dict(row,opened_individually=True,verdict='Analysis-only acceptance: no clipping/invalid envelope/visual spectrum defect identified; ear judgement remains external.'))
(O/'visual-review.json').write_text(json.dumps({'owner':'Codex 2 (WSL CLI)','method':'Each listed final PNG individually opened through view_image. This is waveform/spectrogram inspection, not listening. Seam previews display parent file LUFS/peak metadata alongside a40ms zoom duration.','sheets':review},indent=2)+'\n')
allfiles=m['files'];sfx=[r for r in allfiles if r['channels']==1];loops=[r for r in allfiles if r['channels']==2]
lines=['# SOUND-1 — original coastal foley and ambience','','Codex 2 (WSL CLI),2026-10-25. **Artist pack complete by analysis.** No listening or native gameplay acceptance claimed; Claude owns copying/importing the files and ear-proxy review.','','63mono cue WAVs (21families ×3variants) and3stereo30s ambience loops. Original offline numpy/scipy synthesis only: filtered noise, damped modal resonances, granular water, pressure/pitch envelopes and deterministic variation. No downloaded audio, recordings, external samples, TTS, network access or Unity synthesis render was used. Pillow draws the analysis PNGs only. These are physically inspired approximations, not recordings.','','## File and integration contract','','- All files: RIFF WAVE,44,100Hz,signed16-bit little-endian PCM, uncompressed. SFX mono; ambience stereo. Case-sensitive family names exactly match VoyageAudio.Cue. No normalization metadata or runtime DSP is required.','- Copy SFX to `Assets/Resources/Audio/SFX/<Cue>_<n>.wav` for n=0,1,2; ambience to `Assets/Resources/Audio/Ambience/<Name>.wav`. No files under Assets were authored in this assignment. Existing code-synthesized fallbacks remain the integrator’s choice.','- One-shot cues have7ms cosine endpoint tapers and exact zero first/last PCM samples. Three deterministic variants differ in seed/modal frequencies/noise and duration; choose one per event. Loop the ambience only.','- Ambience has exactly1,323,000frames per channel (30s), periodic whole-cycle noise plus wrapped events; an8ms smooth join on either side keeps a live bed with equal endpoint values and zero join slope. Do not add an end fade or a gap. Preserve the exact sample count when importing/looping.','- UI Select/Click/Purchase are86–134ms and~−32LUFS on the explicitly padded measurement, compared with~−24LUFS normal foley. Gull/SealBark/Bell/Horn target−27LUFS; ambience−28LUFS. Peak headroom may reduce sparse low impacts slightly.','- Winch variants are380/390/400ms with three damped pawl contacts and rope friction. Offline variant-cycled overlap at8and12Hz has unity-gain sum peaks below−4.85dBFS; at0.65gain below−8.59dBFS. This is a bounded two-second synthetic stress case, not a guarantee for every mixer combination. Start at current game gains and judge by ear before changing balance.','','## Recipes and opened contact sheets','','Each SFX sheet contains all three files, each with waveform and absolute-level log-frequency spectrogram (80Hz–16kHz,−100to−15dBFS). Loop sheets show left/right plus a±20ms mono seam preview. Seam row LUFS/peak metadata belongs to the full parent loop; its40ms duration identifies the zoom. All24sheets were individually opened.','','| Family / sheet | Duration range,s | Measured LUFS range | Recipe |','|---|---:|---:|---|']
for name,recipe in RECIPES.items():
    rr=[r for r in sfx if r['family']==name];ds=[r['duration_seconds'] for r in rr];ls=[r['integrated_lufs'] for r in rr]
    lines.append(f'| [{name}](review/{name}.png) | {min(ds):.3f}–{max(ds):.3f} | {min(ls):.2f}–{max(ls):.2f} | {recipe} |')
lines+=['','| Loop / sheet | LUFS | Stereo correlation | Recipe |','|---|---:|---:|---|']
for r in loops:
    name=r['family'];lines.append(f'| [{name}](review/{name}.png) | {r["integrated_lufs"]:.2f} | {r["stereo_correlation"]:.3f} | {AMBIENCE_RECIPES[name]} |')
lines+=['','## Decoded-file checks','','[metrics.json](metrics.json) contains every file’s duration/frame count,format, sample peak,4×polyphase estimated true peak, integrated LUFS,padding, RMS, DC offset, PCM endpoints andSHA256. For loops it also records per-channel seam value/slope steps, interior-difference p99 and seam RMS. [verification.json](verification.json) independently reads every WAV using the standard wave decoder, checks exactly the66expected filenames/hashes/formats/endpoints and24PNGhashes, and records the environment and known-tone meter check. [synthesis inventory](synthesis.json), [opened-sheet receipt](visual-review.json), [delivery receipt](delivery-receipt.json).','','LUFS uses BS.1770 K-weighting with400msblocks/100msstride,−70LUFSabsolute gating and−10LUrelative gating. For cues shorter400ms, zeros extend the measurement to one400msblock; `measurement_zero_padding_seconds` records the amount. This makes those short-clip numbers padded energy measurements, not a claimed native-duration integrated reading. The meter matches a1kHz−20dBFSpeak sine at~−23.00LUFSmono and~−19.99LUFSstereo. The4×polyphase true-peak estimate is not a certified hardware meter.','','Results:']
lines+=[f'- Highest decoded sample peak: **{max(r["sample_peak_dbfs"] for r in allfiles):.3f}dBFS**; highest4×estimated true peak: **{max(r["true_peak_4x_dbtp"] for r in allfiles):.3f}dBTP**, both below−3.',f'- Largest within-family loudness spread: **{max(m["family_lufs_spread"].values()):.3f}LU** (limit2LU).',f'- Largest absolute decoded DC offset: **{max(abs(c) for r in allfiles for c in r["dc_offset_linear"]):.7f}FS** (limit0.0007).','- Every one-shot has zero endpoints and adjacent endpoint samples within3PCMsteps. All loops have exactly zero value and slope discontinuity at the join in both channels; no fade-to-silence.']
lines+=['','| Loop | Seam value step,L/R | Seam slope step,L/R | ±20ms RMS/whole,L/R |','|---|---|---|---|']
for r in loops:
    s=r['loop_seam'];lines.append(f'| {r["family"]} | {s["value_step_linear"]} | {s["slope_step_linear"]} | '+', '.join(f'{x:.3f}' for x in s['join_to_whole_rms_ratio'])+' |')
lines+=['','## Per-file readings','','All levels below are from decoding the actual delivered PCM16WAVs. Full DC/channel/seam details are in metrics.json.','','| WAV | Duration,s | Sample peak,dBFS | Est.true peak,dBTP | LUFS | Measurement zero pad,s |','|---|---:|---:|---:|---:|---:|']
for r in allfiles:lines.append(f'| [{r["file"]}]({r["file"]}) | {r["duration_seconds"]:.3f} | {r["sample_peak_dbfs"]:.2f} | {r["true_peak_4x_dbtp"]:.2f} | {r["integrated_lufs"]:.2f} | {r["measurement_zero_padding_seconds"]:.3f} |')
lines+=['','## Reproduction and remaining acceptance','','Scripts: [dsp.py](../Source/Audio/dsp.py), [build.py](../Source/Audio/build.py), [analyze.py](../Source/Audio/analyze.py), [verify.py](../Source/Audio/verify.py), [run.py](../Source/Audio/run.py), [finalize.py](../Source/Audio/finalize.py). From project root, using an existing Python environment with numpy/scipy (and Pillow for plots):','','```sh','/home/mo/.venvs/catchline-ui/bin/python Art/Source/Audio/run.py build analyze verify','```','','This regenerates the pack and analysis. Individually open all final sheets before running finalize.py again; it binds that review to hashes. Seeds are stable in dsp.py. Package versions are recorded in verification.json; no dependency installation was performed.','','Claude’s remaining acceptance: copy/import uncompressed source WAVs as appropriate, wire Skerries ambience when the runtime supports that location, listen through ear-proxy review for timbre, repetition, scene balance and loop joins, and check fast taps in the real mixer. Current read-only VoyageAudio.cs already discovers SFXvariants0–4and HarbourDay/OpenSea beds; Skerries is supplied for the lead’s integration. No Unity/Assets/runtime/save/watchdog or git changes were made.']
(O/'REPORT.md').write_text('\n'.join(lines)+'\n')
for dest in re.findall(r'\]\(([^)]+)\)',(O/'REPORT.md').read_text()):
    if dest!='delivery-receipt.json':assert (O/dest).is_file(),dest
files=sorted(p for base in [O,R/'Art/Source/Audio'] for p in base.rglob('*') if p.is_file() and p.name!='delivery-receipt.json' and '__pycache__' not in str(p) and '.backup' not in str(p))
receipt={'task':'SOUND-1','owner':'Codex 2 (WSL CLI)','status':'analysis-verified artist pack; ear/native acceptance external','files':[{'file':p.relative_to(R).as_posix(),'bytes':p.stat().st_size,'sha256':sha(p)} for p in files]}
(O/'delivery-receipt.json').write_text(json.dumps(receipt,indent=2)+'\n')
print('SOUND FINAL PASS',len(files),'receipt files',len(review),'opened sheets')
